    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Parameters:
    - M (int): Number of rows in the classroom.
    - N (int): Number of columns in the classroom.
    - K (int): Number of horizontal aisles to add.
    - L (int): Number of vertical aisles to add.
    - D (int): Number of chatting pairs (unused directly, inferred from chatting_pairs length).
    - chatting_pairs (list of tuples): Each tuple contains (Xi, Yi, Pi, Qi) positions of a chatting pair.

    Returns:
    - (str, str): Two space-separated strings representing the optimal row indices for horizontal aisles
      and column indices for vertical aisles. Empty string if no aisles of that type are chosen.
    """
    import itertools

    # Helper to compute aisles that separate a pair
    def horizontal_aisles_for_pair(r1, r2):
        if r1 == r2:
            return set()
        lo, hi = sorted((r1, r2))
        return set(range(lo, hi))  # aisles between lo and hi-1

    def vertical_aisles_for_pair(c1, c2):
        if c1 == c2:
            return set()
        lo, hi = sorted((c1, c2))
        return set(range(lo, hi))  # aisles between lo and hi-1

    # Precompute aisles for each pair
    pair_h_aisles = []
    pair_v_aisles = []
    for (x, y, p, q) in chatting_pairs:
        pair_h_aisles.append(horizontal_aisles_for_pair(x, p))
        pair_v_aisles.append(vertical_aisles_for_pair(y, q))

