    try:
        total_combinations = len(list(itertools.combinations(all_h_aisles, K))) * len(list(itertools.combinations(all_v_aisles, L)))
    except Exception:
        total_combinations = max_combinations + 1

    best_h = ()
    best_v = ()
    best_count = -1

