            # Choose horizontal aisle with max marginal benefit
            best_h_aisle = None
            best_h_gain = -1
            for h in all_h_aisles:
                if h in selected_h:
                    continue
                gain = 0
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and h in pair_h_aisles[idx]:
                        gain += 1
                if gain > best_h_gain:
                    best_h_gain = gain
                    best_h_aisle = h
            if best_h_aisle is not None:
                selected_h.add(best_h_aisle)
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and best_h_aisle in pair_h_aisles[idx]:
                        covered[idx] = True

        for _ in range(L):
            best_v_aisle = None
            best_v_gain = -1
            for v in all_v_aisles:
                if v in selected_v:
                    continue
                gain = 0
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and v in pair_v_aisles[idx]:
                        gain += 1
                if gain > best_v_gain:
                    best_v_gain = gain
                    best_v_aisle = v
            if best_v_aisle is not None:
                selected_v.add(best_v_aisle)
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and best_v_aisle in pair_v_aisles[idx]:
                        covered[idx] = True

        best_h = tuple(sorted(selected_h))
        best_v = tuple(sorted(selected_v))

    # Prepare output strings
    h_str = ' '.join(str(i) for i in sorted(best_h))
    v_str = ' '.join(str(i) for i in sorted(best_v))
    return h_str, v_str

