def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    def parse_statement(stmt: str):
        # Ignore statements that mention a day of the week
        for day in days_of_week:
            if day in stmt:
                return None

        # Remove trailing period and whitespace
        stmt_clean = stmt.strip().rstrip('.')

        # Patterns for guilt statements
        if stmt_clean == "I am guilty":
            return ("speaker", True)
        if stmt_clean == "I am not guilty":
            return ("speaker", False)
        if stmt_clean.endswith(" is guilty"):
            name = stmt_clean[:-len(" is guilty")].strip()
            return (name, True)
        if stmt_clean.endswith(" is not guilty"):
            name = stmt_clean[:-len(" is not guilty")].strip()
            return (name, False)

        # Not a guilt-related statement
        return None

    for speaker, stmts in statements.items():
        for stmt in stmts:
            parsed = parse_statement(stmt)
            if parsed is None:
                continue  # ignore non-guilt or day statements

            target, expected_guilt = parsed
            # Determine the actual guilt status of the target
            if target == "speaker":
                actual_guilt = (speaker == scenario)
            else:
                actual_guilt = (target == scenario)

            # The statement is true if actual_guilt matches expected_guilt
            statement_truth = (actual_guilt == expected_guilt)

            # If speaker is a liar, the statement must be false
            if speaker in liar_count:
                if statement_truth:
                    return False
            else:
                # Non-liar must speak truth
                if not statement_truth:
                    return False

    return True

